#ifndef AOT_NATIVE_ASSETS_H
#define AOT_NATIVE_ASSETS_H
#include "aot_mod.h"
typedef struct {
    const uint8_t *texture,*layout;
    size_t texture_size,layout_size,image_size;
    uint8_t *module;
    void *thunk;
    AotPatch calls[2];
    unsigned active,retain_allocation;
} AotNativeAssets;
/* Caller-owned locally generated bytes MUST remain immutable from successful
 * staging through successful removal, indefinitely after rollback failure.
 * The buffers, state and callback DLL must remain alive for the same interval.
 * const pointers alone do not establish this contract. startup.c enforces it
 * with private read-only owned copies, static state and a pinned DLL.
 * Only the default UIOption pair is replaced; other resource IDs pass through. */
AotStatus aot_native_assets_stage(AotNativeAssets *,uint8_t *module,size_t image_size,
    const uint8_t *texture,size_t texture_size,const uint8_t *layout,size_t layout_size);
AotStatus aot_native_assets_activate(AotNativeAssets *,size_t image_size);
AotStatus aot_native_assets_remove(AotNativeAssets *,size_t image_size);
#endif
